  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('lineTotal with large quantity', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 1500 }), 1500000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 5 * 9500 = 47500
  // vat = 47500 * 21 / 100 = 9975
  // total = 47500 + 9975 = 57475
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 9975);
  assert.equal(totals.total, 57475);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
      { qty: 2, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // 3 * 9500 + 1 * 120000 + 2 * 8500 = 28500 + 120000 + 17000 = 165500
  // vat = 165500 * 21 / 100 = 34755
  // total = 165500 + 34755 = 200255
  assert.equal(totals.subtotal, 165500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 34755);
  assert.equal(totals.total, 200255);
});

test('invoiceTotals with different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1500, vatRate: 21 },
      { qty: 1, unitPrice: 37, vatRate: 9 },
      { qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 3000, vat = 630
  // line 2: 37, vat = 3.33 -> 3
  // line 3: 60000, vat = 0
  // subtotal = 63037, vat = 633, total = 63670
  assert.equal(totals.subtotal, 63037);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 633);
  assert.equal(totals.total, 63670);
});

test('invoiceTotals with empty lines returns zero', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals result is in cents', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 123, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Number.isInteger(totals.subtotal), true);
  assert.equal(Number.isInteger(totals.discount), true);
  assert.equal(Number.isInteger(totals.vat), true);
  assert.equal(Number.isInteger(totals.total), true);
});

