test('invoiceTotals calculates discount', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 5 * 9500 = 47500
  // discount = 47500 * 10 / 100 = 4750
  // amount after discount = 47500 - 4750 = 42750
  // vat = 42750 * 21 / 100 = 8977.5 -> 8978
  // total = 47500 - 4750 + 8978 = 51728
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 8978);
  assert.equal(totals.total, 51728);
});

test('invoiceTotals with multiple lines applies discount to each', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 3 * 9500 = 28500, discount = 2850, amount = 25650, vat = 5386.5 -> 5387
  // line 2: 1 * 120000 = 120000, discount = 6000, amount = 114000, vat = 23940
  // subtotal = 148500, discount = 8850, vat = 5387 + 23940 = 29327
  // But: 5386.5 + 23940 = 29326.5 which rounds to 29326 (banker's rounding)
  // total = 148500 - 8850 + 29326 = 168976
  assert.equal(totals.subtotal, 148500);
  assert.equal(totals.discount, 8850);
  assert.equal(totals.vat, 29326);
  assert.equal(totals.total, 168976);
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 150, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100
  // discount = 150 (would be 150, but clamped per line to 100)
  // amount = 100 - 100 = 0
  // vat = 0
  // total = max(0, 100 - 100 + 0) = 0
  assert.equal(totals.total, 0);
});

test('addLine accepts discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const r2 = addLine(r.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine rejects invalid discountPercent', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1, discountPercent: -10 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1, discountPercent: 120 }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine defaults discountPercent to 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const r2 = addLine(r.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 0);
});

test('createInvoice applies tier discount for gold customers', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-001 is gold tier, should get 5% discount
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies tier discount for silver customers', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-003 is silver tier, should get 2.5% discount
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies tier discount for standard customers', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-002 is standard tier, should get 0% discount
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discountPercent overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  // C-001 is gold (5%), but explicit 10% should win
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice explicit 0% overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  // C-001 is gold (5%), but explicit 0% should win
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice mixes tier and explicit discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 },
      { sku: 'BRAND-BOOK', qty: 2, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  // C-001 is gold (5%)
  assert.equal(r.value.lines[0].discountPercent, 5);
  // Explicit 15%
  assert.equal(r.value.lines[1].discountPercent, 15);
  // Explicit 0%
  assert.equal(r.value.lines[2].discountPercent, 0);
});

test('createInvoice tier discount affects invoice totals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  // 5 * 9500 = 47500, 5% discount = 2375
  // amount after discount = 45125, vat = 45125 * 21 / 100 = 9476.25 -> 9476
  // total = 47500 - 2375 + 9476 = 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

test('lineVat calculates VAT on discounted amount', () => {
  // 100 cents, no discount, 21% VAT = 21 cents
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 0 }), 21);

  // 100 cents, 10% discount (10 cents off), 90 cents taxable, 21% = 18.9 -> 19 cents
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 10 }), 19);

  // 0% VAT
  assert.equal(lineVat({ qty: 5, unitPrice: 9500, vatRate: 0 }), 0);
});

test('lineVat with undefined discountPercent', () => {
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21 }), 21);
});

test('lineVat clamps at 0', () => {
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 0 }), 0);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21 },
      { qty: 1, unitPrice: 10000, vatRate: 9 },
      { qty: 1, unitPrice: 10000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 30000
  // line 1 vat = 10000 * 21 / 100 = 2100
  // line 2 vat = 10000 * 9 / 100 = 900
  // line 3 vat = 0
  // vat = 3000
  // total = 30000 + 3000 = 33000
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.vat, 3000);
  assert.equal(totals.total, 33000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { qty: 1, unitPrice: 10000, vatRate: 9, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 10000, discount 1000, amount 9000, vat = 1890
  // line 2: 10000, discount 500, amount 9500, vat = 855
  // subtotal = 20000, discount = 1500, vat = 2745
  // total = 20000 - 1500 + 2745 = 21245
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 2745);
  assert.equal(totals.total, 21245);
});

